// ===== Extruder03 : ค่าชั่งน้ำหนักจาก PLC Omron NJ 192.168.250.1 (D554) =====
// msg.payload จาก FINS Read = [D554, D555] (แบบ unsigned)
// ยังไม่รู้ว่า PLC เก็บน้ำหนักแบบไหน -> แสดงทุกแบบให้เทียบกับจอเครื่อง แล้วเลือก FORMAT ให้ตรง
const FORMAT = "int16";   // "int16" | "uint16" | "int32" | "float"
const DIV    = 1;         // ถ้าจอเครื่องโชว์ 12.5 แต่ค่าได้ 125 -> ใส่ 10  (ได้ 1250 -> 100)
const UNIT   = "kg";

const w = Array.isArray(msg.payload) ? msg.payload.map(v => v & 0xFFFF) : null;
if (!w || w.length < 2) { node.status({ fill: "red", shape: "ring", text: "อ่านไม่ได้" }); return [null, { payload: { error: "ข้อมูลไม่ครบ", raw: msg.payload } }]; }

const lo = w[0], hi = w[1];                       // Omron: word ต่ำอยู่ address น้อย (D554), word สูงที่ D555
const b = Buffer.alloc(4); b.writeUInt16BE(hi, 0); b.writeUInt16BE(lo, 2);
const all = {
    int16:  lo > 32767 ? lo - 65536 : lo,
    uint16: lo,
    int32:  b.readInt32BE(0),
    float:  Math.round(b.readFloatBE(0) * 1000) / 1000
};
const weight = Math.round(all[FORMAT] / DIV * 1000) / 1000;

flow.set("ex03_weight", { weight, unit: UNIT, ts: Date.now() });
node.status({ fill: "green", shape: "dot", text: weight + " " + UNIT + "  (D554=" + lo + ")" });

return [
    { payload: { machine: "Extruder03", weight, unit: UNIT, time: new Date().toLocaleTimeString("th-TH") } },
    { payload: { "D554 (raw)": lo, "D555 (raw)": hi,
                 "ถ้าเป็น INT 16 บิต": all.int16, "ถ้าเป็น UINT 16 บิต": all.uint16,
                 "ถ้าเป็น DINT 32 บิต (D554-555)": all.int32, "ถ้าเป็น REAL ทศนิยม (D554-555)": all.float,
                 "ใช้อยู่": FORMAT + (DIV !== 1 ? " / " + DIV : "") } }
];
